(7, 13, '_form', '<div class=\"contact-form-area\">\n    <h3>Liên hệ Techzhome</h3>\n    <div>\n        <div class=\"row\">\n            <div class=\"col-lg-12 mb-20\">\n                <div class=\"form-inner\">\n                    <label>Tên quý khách*</label>\n                    [text* text-426 placeholder \"Nhập tên quý khách\"]\n                </div>\n            </div>\n            <div class=\"col-lg-6 mb-20\">\n                <div class=\"form-inner\">\n                    <label>Điện thoại liên hệ*</label>\n                    [number* number-873 placeholder \"Nhập số điện thoại\"]\n                </div>\n            </div>\n            <div class=\"col-lg-6 mb-20\">\n                <div class=\"form-inner\">\n                    <label>Email*</label>\n                    [email* email-124 placeholder \"Nhập Email....\"]\n                </div>\n            </div>\n            <div class=\"col-lg-12 mb-30\">\n                <div class=\"form-inner\">\n                    <label>Yêu cầu*</label>\n                    [textarea* textarea-499 placeholder \"Nhập yêu cầu\"]\n                </div>\n            </div>\n            <div class=\"col-lg-12\">\n                <div class=\"form-inner\">\n                    <button class=\"primary-btn1 btn-hover\" type=\"submit\">\n                       Gửi ngay\n                    </button>\n                </div>\n            </div>\n        </div>\n    </div>\n</div>'),
(8, 13, '_mail', 'a:9:{s:6:\"active\";b:1;s:7:\"subject\";s:26:\"[_site_title] \"[text-426]\"\";s:6:\"sender\";s:36:\"[_site_title] <nnduyquang@gmail.com>\";s:9:\"recipient\";s:19:\"[_site_admin_email]\";s:4:\"body\";s:235:\"<p><strong>Name: </strong>[text-426]</p>\n<p><strong>Email: </strong>[email-124]</p>\n<p><strong>Phone: </strong>[number-873]</p>\n<p><strong>Request: </strong>[textarea-499]</p>\n\n-- \nSend From Page [text-426] ([_site_title] [_site_url]).\";s:18:\"additional_headers\";s:21:\"Reply-To: [email-124]\";s:11:\"attachments\";s:0:\"\";s:8:\"use_html\";b:0;s:13:\"exclude_blank\";b:0;}'),
(9, 13, '_mail_2', 'a:9:{s:6:\"active\";b:0;s:7:\"subject\";s:30:\"[_site_title] \"[your-subject]\"\";s:6:\"sender\";s:36:\"[_site_title] <nnduyquang@gmail.com>\";s:9:\"recipient\";s:12:\"[your-email]\";s:4:\"body\";s:220:\"Message Body:\n[your-message]\n\n-- \nThis email is a receipt for your contact form submission on our website ([_site_title] [_site_url]) in which your email address was used. If that was not you, please ignore this message.\";s:18:\"additional_headers\";s:29:\"Reply-To: [_site_admin_email]\";s:11:\"attachments\";s:0:\"\";s:8:\"use_html\";b:0;s:13:\"exclude_blank\";b:0;}'),
(10, 13, '_messages', 'a:22:{s:12:\"mail_sent_ok\";s:100:\"Cảm ơn quý khách đã liên hệ. Chúng tôi sẽ phản hồi cho quý khách trong vòng 24h\";s:12:\"mail_sent_ng\";s:71:\"There was an error trying to send your message. Please try again later.\";s:16:\"validation_error\";s:61:\"Quý khách vui lòng kiểm tra lại thông tin đã nhập\";s:4:\"spam\";s:71:\"There was an error trying to send your message. Please try again later.\";s:12:\"accept_terms\";s:69:\"You must accept the terms and conditions before sending your message.\";s:16:\"invalid_required\";s:31:\"Thông tin không để trống\";s:16:\"invalid_too_long\";s:32:\"This field has a too long input.\";s:17:\"invalid_too_short\";s:33:\"This field has a too short input.\";s:13:\"upload_failed\";s:46:\"There was an unknown error uploading the file.\";s:24:\"upload_file_type_invalid\";s:49:\"You are not allowed to upload files of this type.\";s:21:\"upload_file_too_large\";s:31:\"The uploaded file is too large.\";s:23:\"upload_failed_php_error\";s:38:\"There was an error uploading the file.\";s:12:\"invalid_date\";s:61:\"Vui lòng nhập ngày tháng theo định dạng YYYY-MM-DD.\";s:14:\"date_too_early\";s:64:\"Trường dữ liệu này có ngày sớm hơn ngày cho phép.\";s:13:\"date_too_late\";s:64:\"Trường dữ liệu này có ngày trễ hơn ngày cho phép.\";s:14:\"invalid_number\";s:37:\"Vui lòng nhập vào một con số.\";s:16:\"number_too_small\";s:57:\"Trường dữ liệu này có một con số quá nhỏ.\";s:16:\"number_too_large\";s:57:\"Trường dữ liệu này có một con số quá lớn.\";s:23:\"quiz_answer_not_correct\";s:30:\"Câu trả lời chưa đúng.\";s:13:\"invalid_email\";s:36:\"Vui lòng nhập địa chỉ email.\";s:11:\"invalid_url\";s:21:\"Vui lòng nhập URL.\";s:11:\"invalid_tel\";s:38:\"Vui lòng nhập số điện thoại.\";}'),
